		public bool SignalBoostEnabled { get; init; } = true;

		public bool BufferEnabled { get; init; } = true;

		public bool SupercriticalEnabled { get; init; } = true;

		public bool DefragmentEnabled { get; init; } = true;

		public bool ModdedEnabled { get; init; } = true;

		public bool FlakCannonEnabled { get; init; } = true;

