		public bool GunkUpEnabled { get; init; } = true;

		public bool CompileDriverEnabled { get; init; } = true;

		public bool TurboEnabled { get; init; } = true;

		public bool MeteorStrikeEnabled { get; init; } = true;

		public static AnimationSettings Current { get; internal set; } = new AnimationSettings();

		internal static string FilePath => ProjectSettings.GlobalizePath("user://mod_settings/MoreDefectAnimations.json");

		internal static void Load()
		{
			try
			{
				if (File.Exists(FilePath))
				{
					Current = JsonSerializer.Deserialize<AnimationSettings>(File.ReadAllText(FilePath)) ?? new AnimationSettings();
				}
			}
			catch (Exception error)
			{
				ModEntry.Log(error);
			}
		}

		internal static void Save(AnimationSettings value)
		{
			if (!(value == Current) || !File.Exists(FilePath))
			{
				Directory.CreateDirectory(Path.GetDirectoryName(FilePath));
				string text = FilePath + ".tmp";
				File.WriteAllText(text, JsonSerializer.Serialize(value, new JsonSerializerOptions
				{
					WriteIndented = true
				}));
				File.Move(text, FilePath, overwrite: true);
				Current = value;
				PresentationPreloader.Cancel();
				if (!value.Enabled || !value.CoolheadedEnabled)
				{
					CoolheadedSession.Reset();
				}
				if (!value.Enabled || !value.ChargeBatteryEnabled)
				{
					ChargeBatterySession.Reset();
				}
				if (!value.Enabled || !value.BiasedCognitionEnabled)
				{
					BiasedCognitionSession.Reset();
				}
				if (!value.Enabled || !value.HotfixEnabled)
				{
					HotfixSession.Reset();
				}
				if (!value.Enabled || !value.SignalBoostEnabled)
				{
					SignalSession.Reset();
				}
				else
				{
					SignalSession.EnsureCurrent();
				}
				if (!value.Enabled || !value.BufferEnabled)
				{
					BufferSession.Reset();
				}
				else
				{
					BufferSession.EnsureCurrent();
				}
				if (!value.Enabled || !value.SupercriticalEnabled)
				{
					SupercriticalSession.Reset();
				}
				if (!value.Enabled || !value.DefragmentEnabled)
				{
					DefragmentSession.Reset();
				}
				if (!value.Enabled || !value.FlakCannonEnabled)
				{
					FlakSession.Reset();
				}
				else
				{
					FlakSession.EnsureCurrent(restore: true);
				}
				if (!value.Enabled || !value.BulkUpEnabled)
				{
					BulkUpSession.Reset();
				}
				if (!value.Enabled || !value.HologramEnabled)
				{
					HologramSession.Reset();
				}
				if (!value.Enabled || !value.IceLanceEnabled)
				{
					IceLanceSession.Reset();
				}
				if (!value.Enabled || !value.ModdedEnabled)
				{
					ModdedSession.Reset();
				}
				if (!value.Enabled || !value.DualcastEnabled || !value.QuadcastEnabled)
				{
					MulticastSession.Reset();
				}
				if (!value.Enabled || !value.ConsumingShadowEnabled)
				{
					ShadowSession.Reset();
				}
				if (!value.Enabled || !value.TurboEnabled)
				{
					TurboSession.Reset();
				}
				CardAttackSession.ResetDisabled();
				if (!value.Enabled || !value.MeteorStrikeEnabled)
				{
					MeteorSession.Reset();
				}
			}
		}

