							3 => Triangle(num3 % num4, timeline.Count), 
							4 => Math.Max(timeline.Count - 1 - num3, 0), 
							5 => timeline.Count - 1 - num3 % timeline.Count, 
							6 => Triangle((num3 + timeline.Count - 1) % num4, timeline.Count), 
							_ => num3, 
						};
