		internal void Advance(double dt, bool electric)
		{
			_pending = Math.Min(_pending + Math.Max(0.0, dt), 0.08);
			_electric = electric;
			((CanvasItem)_arcSlot).Visible = _guard.AllowsDisplay() && electric;
			if (!electric)
			{
				GpuParticles2D[] arcs = Arcs;
				for (int i = 0; i < arcs.Length; i++)
				{
					arcs[i].Emitting = false;
				}
				return;
			}
			_arcClock += dt;
			if (_arcClock >= 0.6)
			{
				_arcClock %= 0.6;
				Pulse(counted: false);
			}
		}

		internal void TriggerParticles(bool enabled)
		{
			_electric = enabled;
			_arcClock = 0.0;
			Pulse(counted: true);
		}

		private void Pulse(bool counted)
		{
			bool flag = _electric && _guard.AllowsDisplay();
			GpuParticles2D[] arcs = Arcs;
			foreach (GpuParticles2D val in arcs)
			{
				((CanvasItem)val).Visible = _electric;
				if (flag)
				{
					val.Restart();
					val.Emitting = true;
				}
				else
				{
					val.Emitting = false;
				}
			}
			if (counted && flag)
			{
				ParticleTriggers++;
			}
		}

