		{
			bool ok = false;
			try
			{
				await task;
				ok = true;
			}
			catch
			{
			}
			finally
			{
				Open = false;
				if (!ok)
				{
					Visual?.Dispose();
				}
			}
		}
	}
	internal sealed class ShadowChannel(ShadowCall call, OrbModel orb)
	{
		internal readonly ShadowCall Call = call;

		internal readonly OrbModel Orb = orb;

		internal readonly int Index = call.Channels++;

		internal bool Confirmed;

		internal async Task Observe(Task task)
		{
			try
			{
				await task;
			}
			catch
			{
			}
			finally
			{
				if (!Confirmed)
				{
					call.Visual?.Invalidate(Index);
				}
			}
		}
	}
