				return;
			}
			NCreature creatureNode = creature.GetCreatureNode();
			NCombatRoom instance = NCombatRoom.Instance;
			if (creatureNode != null && instance != null && GodotObject.IsInstanceValid((GodotObject)(object)creatureNode) && ((Node)creatureNode).IsInsideTree() && !creatureNode.IsPlayingDeathAnimation)
