			}
		}

		private void Died(Creature creature)
		{
			Dispose();
		}

		private void Frame()
		{
			if (_disposed)
			{
				return;
			}
			try
			{
				if (!CoolheadedSession.Allowed || !AnimationSettings.Current.Enabled || !AnimationSettings.Current.DefragmentEnabled || !CombatManager.Instance.IsInProgress || CombatManager.Instance.IsEnding || !_actor.Entity.IsAlive || _actor.IsPlayingDeathAnimation || _actor.Entity.CombatState != _combat)
				{
					Dispose();
				}
				else if (!_tree.Paused && ((Node)_actor).CanProcess())
				{
