	internal sealed class FlakSession : IDisposable
	{
		internal sealed class PlayLease : IDisposable
		{
			private FlakSession? _session;

			internal PlayLease(FlakSession session)
			{
				_session = session;
				session.Playback.BeginPlay();
			}

			public void Dispose()
			{
				FlakSession session = _session;
				_session = null;
