				{
					session.Playback.EndPlay();
				}
			}
		}

		private static readonly Dictionary<NCreature, FlakSession> Sessions = new Dictionary<NCreature, FlakSession>(ReferenceEqualityComparer.Instance);

		internal readonly FlakPlayback Playback = new FlakPlayback();

		private readonly NCreature _actor;

		private readonly NCombatRoom _room;

		private readonly CombatState _combat;

		private readonly SceneTree _tree;

		private readonly CardPile _hand;

		private Node2D _body;

		private Creature? _target;

		private FlakAudio? _audio;

		private bool _dirty = true;

		private bool _disposed;

		internal static int ActiveCount => Sessions.Count;

		internal NativeFlak? Visual { get; private set; }

		internal int RemainingCount { get; private set; }

		internal int Recounts { get; private set; }

		internal bool AudioPlaying => _audio?.Playing ?? false;

		internal static FlakSession? For(NCreature actor)
		{
			return Sessions.GetValueOrDefault(actor);
		}

		internal static void EnsureCurrent(bool restore = false)
		{
			if (!CoolheadedSession.Allowed || NCombatRoom.Instance == null)
			{
				return;
			}
			RunState val = RunManager.Instance.DebugOnlyGetState();
			if (val == null)
			{
				return;
			}
			foreach (Player player in val.Players)
			{
				NCreature creatureNode = player.Creature.GetCreatureNode();
				if (creatureNode == null)
				{
					continue;
				}
				bool flag = For(creatureNode) != null;
				Ensure(creatureNode);
				if (restore && !flag)
				{
					FlakSession flakSession = For(creatureNode);
					if (flakSession != null)
					{
						flakSession.Playback.Entrance = (flakSession.Playback.Present ? 1.97 : 0.0);
						flakSession.Visual?.Refresh();
					}
				}
			}
		}

		internal static void Ensure(NCreature actor)
		{
			if (!CoolheadedSession.Allowed || !AnimationSettings.Current.Enabled || !AnimationSettings.Current.FlakCannonEnabled || For(actor) != null || CombatManager.Instance.IsEnding)
			{
				return;
			}
			NCombatRoom instance = NCombatRoom.Instance;
			Creature entity = actor.Entity;
			if (!GodotObject.IsInstanceValid((GodotObject)(object)actor) || !((Node)actor).IsInsideTree() || !actor.HasSpineAnimation || instance == null || !entity.IsAlive)
			{
				return;
			}
			Player player = entity.Player;
			if (!(((player != null) ? ((object)player.Character).GetType().Name : null) != "Defect") && entity.Player.PlayerCombatState != null)
			{
				ICombatState combatState = entity.CombatState;
				CombatState val = (CombatState)(object)((combatState is CombatState) ? combatState : null);
				if (val != null)
				{
					FlakSession flakSession = new FlakSession(actor, instance, val);
					Sessions.Add(actor, flakSession);
					flakSession.Recount();
					flakSession.RefreshBinding();
				}
			}
		}

		internal static FlakSession? Get(FlakCannon card)
		{
			NCreature creatureNode = ((CardModel)card).Owner.Creature.GetCreatureNode();
			if (creatureNode == null)
			{
				return null;
			}
			Ensure(creatureNode);
			FlakSession flakSession = For(creatureNode);
			if (flakSession == null || !flakSession.CanAnimate())
			{
				return null;
			}
			return flakSession;
		}

		internal static void Dirty(CardModel card)
		{
			Player owner = card.Owner;
			NCreature val = ((owner != null) ? owner.Creature.GetCreatureNode() : null);
			if (val != null)
			{
				FlakSession flakSession = For(val);
				if (flakSession != null)
				{
					flakSession._dirty = true;
				}
			}
		}

		private FlakSession(NCreature actor, NCombatRoom room, CombatState combat)
		{
			_actor = actor;
			_room = room;
			_combat = combat;
			_body = actor.Body;
			_tree = ((Node)room).GetTree();
			Player player = actor.Entity.Player;
			_hand = CardPile.Get((PileType)2, player);
			_hand.ContentsChanged += Changed;
			((Node)actor).TreeExiting += Dispose;
			((Node)room).TreeExiting += Dispose;
			actor.Entity.Died += Died;
			_tree.ProcessFrame += Frame;
		}

		private void Changed()
		{
			_dirty = true;
		}

		private void Recount()
		{
			_dirty = false;
			Recounts++;
			RemainingCount = _hand.Cards.OfType<FlakCannon>().Count();
			Playback.Presence(RemainingCount > 0);
		}

		private bool CanAnimate()
		{
			if (!_disposed && CoolheadedSession.Allowed && AnimationSettings.Current.Enabled && AnimationSettings.Current.FlakCannonEnabled && !CombatManager.Instance.IsEnding && _actor.Entity.IsAlive && _actor.Entity.CombatState == _combat && GodotObject.IsInstanceValid((GodotObject)(object)_actor.Body))
			{
				return SpineGuard.Get(_actor.Body, CoolheadedAssets.Get()) != null;
			}
			return false;
		}

		internal PlayLease? HoldForPlay()
		{
			if (!CanAnimate())
			{
				return null;
			}
			if (_dirty)
			{
				Recount();
			}
			PlayLease playLease = new PlayLease(this);
			try
			{
				RefreshBinding();
				Visual?.Refresh();
				return playLease;
			}
			catch
			{
				playLease.Dispose();
				throw;
			}
		}

		internal int Begin(bool charging = false)
		{
			if (!CanAnimate())
			{
				return 0;
			}
			if (_dirty)
			{
				Recount();
			}
			int result = Playback.Begin(charging);
			RefreshBinding();
			if (_audio == null)
			{
				_audio = new FlakAudio((Node)(object)_actor);
			}
			Visual?.Refresh();
			_audio.Update(Playback, paused: false);
			return result;
		}

		internal bool Hit(int token, Creature target)
		{
			if (!CanAnimate() || token != Playback.Generation || !Playback.Active)
			{
				return false;
			}
			bool flag = Playback.Hit(token);
			_target = target;
			RefreshBinding();
			Visual?.Hit(target, flag);
			_audio?.Update(Playback, paused: false);
			if (flag)
			{
				NGame instance = NGame.Instance;
				if (instance != null)
				{
					instance.ScreenShake((ShakeStrength)3, (ShakeDuration)2, 0f);
				}
			}
			return true;
		}

		internal void Complete(int token, bool success)
		{
			if (_disposed)
			{
				return;
			}
			if (!CanAnimate())
			{
				Dispose();
				return;
			}
			if (_dirty)
			{
				Recount();
			}
			if (Playback.Complete(token, success))
			{
				Visual?.Refresh();
				NGame instance = NGame.Instance;
				if (instance != null)
				{
					instance.ScreenShake((ShakeStrength)4, (ShakeDuration)1, 180f);
				}
			}
			_audio?.Update(Playback, paused: false);
		}

		internal void CancelCharge(int token)
		{
			if (!_disposed && token == Playback.Generation && Playback.Hits == 0)
			{
				Complete(token, success: false);
			}
		}

		private void RefreshBinding()
		{
			Node2D body = _actor.Body;
			if (Visual != null && (body != _body || !Visual.Current))
			{
				DropVisual();
			}
			_body = body;
			if (Visual == null && (Playback.KeepDeployed || Playback.Progress > 0.0 || Playback.Active) && GodotObject.IsInstanceValid((GodotObject)(object)body) && SpineGuard.Get(body, CoolheadedAssets.Get()) != null)
			{
