				Visual.Target = _target;
			}
		}

		private void DropVisual()
		{
			NativeFlak? visual = Visual;
			Visual = null;
			visual?.Dispose();
		}

		private void Died(Creature _)
		{
			Dispose();
		}

		private void Frame()
		{
			if (_disposed)
			{
				return;
			}
			try
			{
				if (!CoolheadedSession.Allowed || !AnimationSettings.Current.Enabled || !AnimationSettings.Current.FlakCannonEnabled || CombatManager.Instance.IsEnding || !_actor.Entity.IsAlive || _actor.IsPlayingDeathAnimation || _actor.Entity.CombatState != _combat)
				{
					Dispose();
					return;
				}
				if (_dirty)
				{
					Recount();
				}
				if (!CombatManager.Instance.IsInProgress || _tree.Paused || !((Node)_actor).CanProcess())
				{
					Visual?.Freeze();
					_audio?.Update(Playback, paused: true);
					return;
				}
				RefreshBinding();
				if (Visual != null && Visual.Current)
				{
					if (Visual.CanDisplay)
					{
						Playback.Advance(((Node)_actor).GetProcessDeltaTime());
					}
					Visual.Refresh();
				}
				FlakAudio? audio = _audio;
				if (audio != null)
				{
					FlakPlayback playback = Playback;
					NativeFlak? visual = Visual;
					audio.Update(playback, visual == null || !visual.CanDisplay);
				}
				if (!Playback.Active && !Playback.KeepDeployed && Playback.Entrance == 0.0)
				{
					DropVisual();
				}
			}
			catch (Exception error)
			{
				ModEntry.Log(error);
				Dispose();
			}
		}

		internal static void Reset()
		{
			FlakSession[] array = Sessions.Values.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Dispose();
			}
		}

		public void Dispose()
		{
			if (!_disposed)
			{
