	internal sealed class MeteorCall(MeteorStrike card)
	{
		internal readonly MeteorStrike Card = card;

		internal readonly object? Combat = ((CardModel)card).Owner.Creature.CombatState;

		internal bool Open = true;

		internal int Channels;

		internal MeteorSession? Visual;

		internal bool Valid
		{
			get
			{
				if (Open && MeteorSession.Allowed)
				{
					return Combat == ((CardModel)card).Owner.Creature.CombatState;
				}
				return false;
			}
		}

		internal async Task Observe(Task original)
		{
			try
			{
				await original;
			}
			catch
			{
				Visual?.Dispose();
			}
			finally
			{
				Open = false;
			}
		}
	}
	internal sealed class MeteorChannel(MeteorCall call, OrbModel orb)
	{
		internal readonly MeteorCall Call = call;

		internal readonly OrbModel Orb = orb;

		internal readonly int Index = call.Channels++;

		internal bool Confirmed;

		internal async Task Observe(Task original)
		{
			try
			{
				await original;
			}
			catch
			{
			}
			finally
			{
				if (!Confirmed)
				{
					call.Visual?.Invalidate(Index);
				}
			}
		}
	}
