	[HarmonyPatch(typeof(NOrbManager), "AddOrbAnim")]
	internal static class MeteorOrbAddedPatch
	{
		[HarmonyPostfix]
		private static void Postfix(NOrbManager __instance)
		{
			try
			{
				MeteorChannel channel = MeteorContext.Channel.Value;
				if (channel != null && channel.call.Valid)
				{
					List<NOrb> list = NativeOrbSlots.Nodes(__instance);
					int num = list.FindIndex((NOrb n) => n.Model == channel.orb);
					if (num >= 0)
					{
						channel.Confirmed = true;
						channel.call.Visual?.Confirm(channel.Index, channel.orb, list[num], num);
					}
				}
			}
			catch (Exception error)
			{
				ModEntry.Log(error);
			}
		}
	}
