	internal sealed class ModdedPlayback
	{
		internal readonly ModdedMotion Motion = new ModdedMotion();

		internal bool Equipped;

		internal int Plays;

		internal int Generation;

		internal string? Effect;

		internal double Age;

		internal double Duration;

		internal bool Retracting { get; private set; }

		internal bool CardPlayed()
		{
			Plays++;
			if (Equipped && !Retracting)
			{
				return false;
			}
			Equipped = true;
			Retracting = false;
			Motion.SetRetracting(retracting: false);
			return true;
		}

		internal void EndTurn()
		{
			if (Equipped && !Retracting)
			{
				Retracting = true;
				Effect = null;
				Motion.SetRetracting(retracting: true);
			}
		}

		internal bool Action(string action, ModdedAssets.Profile profile)
		{
			if (!Equipped || Retracting)
			{
				return false;
			}
			string text;
			switch (action)
			{
			case "PowerUp":
			case "process":
				text = "countdown";
				break;
			case "Attack":
			case "attack":
			case "Cast":
			case "cast":
				text = "flash";
				break;
			default:
				text = null;
				break;
			}
			string text2 = text;
			if (text2 == null)
			{
				return false;
			}
			Effect = text2;
			Age = 0.0;
			Duration = ((text2 == "flash") ? (profile.End - profile.Start) : profile.End);
			Generation++;
			return true;
		}

		internal void Advance(double dt)
		{
			if (!(dt > 0.0) || !Equipped)
			{
				return;
			}
			Motion.Time += dt;
			if (Retracting && Motion.DeploymentTime <= 1E-09)
			{
				Equipped = false;
				Effect = null;
			}
			else if (Effect != null)
			{
				Age = Math.Min(Duration, Age + dt);
				if (Age >= Duration - 1E-09)
				{
					Effect = null;
				}
			}
		}

		internal ModdedAssets.ClockValue Sample(ModdedAssets.Profile profile)
		{
			//IL_002c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Unknown result type (might be due to invalid IL or missing references)
			if (Effect == null || Retracting || Motion.DeploymentTime < 0.78)
			{
				return new ModdedAssets.ClockValue(-1, 0f, Vector2.Zero, Vector2.Zero, Vector2.Zero);
			}
			double num = Age + ((Effect == "flash") ? profile.Start : 0.0);
			ModdedAssets.ClockKey[] clock = profile.Clock;
			int i;
			for (i = 0; i + 1 < clock.Length && clock[i + 1].Time <= num; i++)
			{
			}
			ModdedAssets.ClockKey clockKey = clock[i];
			float num2 = clockKey.After.Alpha;
			if (i + 1 < clock.Length)
			{
				num2 = Mathf.Lerp(num2, clock[i + 1].Before.Alpha, (float)Math.Clamp((num - clockKey.Time) / (clock[i + 1].Time - clockKey.Time), 0.0, 1.0));
			}
			return clockKey.After with
			{
				Alpha = num2
			};
		}
