		internal void Step(float dt)
		{
			if (dt > 0f)
			{
				_wireMotion.Step(dt);
			}
		}

		internal void Rebind()
		{
			SolverTime = Time;
			_wireMotion.Reset();
		}
	}
	internal sealed class ModdedPngAssets
	{
		internal sealed record Sample(double Time, float[] Values, float[] Slopes);

		internal sealed record Frame(double Time, Texture2D Texture, int[] Indices, Vector2[] Uv, Vector2[] FaceUv, float[]?[] Bindings, Sample[] Samples, int Count);

		private static ModdedPngAssets? _cache;

		internal readonly Frame[] Frames;

		internal static ModdedPngAssets Get()
		{
			return _cache ?? (_cache = new ModdedPngAssets());
		}

		private static float[] Floats(JsonElement e)
		{
			return (from v in e.EnumerateArray()
				select v.GetSingle()).ToArray();
		}

		private static Vector2[] Pairs(JsonElement e)
		{
			float[] a = Floats(e);
			return Enumerable.Range(0, a.Length / 2).Select((Func<int, Vector2>)((int i) => new Vector2(a[i * 2], a[i * 2 + 1]))).ToArray();
		}

		private ModdedPngAssets()
		{
			string folder = Path.Combine(ModEntry.DirectoryPath, "assets", "modded", "png");
			using FileStream stream = File.OpenRead(Path.Combine(folder, "keyframes.br"));
			using BrotliStream utf8Json = new BrotliStream(stream, CompressionMode.Decompress);
			using JsonDocument jsonDocument = JsonDocument.Parse(utf8Json);
			Frames = jsonDocument.RootElement.GetProperty("frames").EnumerateArray().Select(delegate(JsonElement f)
			{
				Image val = Image.LoadFromFile(Path.Combine(folder, f.GetProperty("file").GetString()));
				try
				{
					if (val == null || val.IsEmpty())
					{
						throw new IOException("Missing Modded PNG keyframe");
					}
					Sample[] samples = (from p in f.GetProperty("poses").EnumerateArray()
						select new Sample(p.GetProperty("time").GetDouble(), new string[3] { "vertices", "eyeX", "eyeY" }.SelectMany((string k) => Floats(p.GetProperty(k))).ToArray(), new string[3] { "vertices", "eyeX", "eyeY" }.SelectMany((string k) => Floats(p.GetProperty("slopes").GetProperty(k))).ToArray())).ToArray();
					return new Frame(f.GetProperty("time").GetDouble(), (Texture2D)(object)ImageTexture.CreateFromImage(val), ModdedAssets.Ints(f.GetProperty("indices")), Pairs(f.GetProperty("uv")), Pairs(f.GetProperty("faceUV")), (from b in f.GetProperty("bindings").EnumerateArray()
						select (b.ValueKind != JsonValueKind.Null) ? Floats(b) : null).ToArray(), samples, f.GetProperty("vertexCount").GetInt32());
				}
				finally
				{
					((IDisposable)val)?.Dispose();
				}
			})
				.ToArray();
			if (Frames.Length != 12)
			{
				throw new InvalidDataException("Modded requires twelve PNG keyframes");
			}
		}

		internal static void SampleInto(Frame frame, double time, float[] output)
		{
			Sample[] samples = frame.Samples;
			time = Math.Clamp(time, samples[0].Time, samples[^1].Time);
			int i;
			for (i = 1; i < samples.Length - 1 && samples[i].Time < time; i++)
			{
			}
			Sample sample = samples[i - 1];
			Sample sample2 = samples[i];
			double num = sample2.Time - sample.Time;
			double num2 = (time - sample.Time) / num;
			double num3 = num2 * num2;
			double num4 = num3 * num2;
			float num5 = (float)(2.0 * num4 - 3.0 * num3 + 1.0);
			float num6 = (float)((num4 - 2.0 * num3 + num2) * num);
			float num7 = (float)(-2.0 * num4 + 3.0 * num3);
			float num8 = (float)((num4 - num3) * num);
			for (int j = 0; j < output.Length; j++)
			{
				output[j] = num5 * sample.Values[j] + num6 * sample.Slopes[j] + num7 * sample2.Values[j] + num8 * sample2.Slopes[j];
			}
		}
	}
