		internal static void Start(Modded card)
		{
			if (!CoolheadedSession.Allowed || !AnimationSettings.Current.Enabled || !AnimationSettings.Current.ModdedEnabled || !CombatManager.Instance.IsInProgress || CombatManager.Instance.IsEnding)
			{
				return;
			}
