			NCombatRoom instance = NCombatRoom.Instance;
			if (creatureNode != null && instance != null && GodotObject.IsInstanceValid((GodotObject)(object)creatureNode) && ((Node)creatureNode).IsInsideTree() && !creatureNode.IsPlayingDeathAnimation && creatureNode.HasSpineAnimation && SpineGuard.Get(creatureNode.Body, CoolheadedAssets.Get()) != null)
			{
				long timestamp = Stopwatch.GetTimestamp();
				ModdedSession moddedSession = For(creatureNode);
				if (moddedSession == null)
				{
					moddedSession = new ModdedSession(creatureNode, instance, val);
					Sessions.Add(creatureNode, moddedSession);
				}
				moddedSession.Playback.CardPlayed();
				moddedSession.RefreshBinding();
				LastStartCpuMilliseconds = Stopwatch.GetElapsedTime(timestamp).TotalMilliseconds;
			}
		}

		internal static void Action(Creature creature, string category)
		{
			if (!creature.IsAlive)
			{
				return;
			}
			NCreature creatureNode = creature.GetCreatureNode();
			if (creatureNode != null)
			{
				ModdedSession moddedSession = For(creatureNode);
				if (moddedSession != null && !moddedSession._disposed)
				{
					moddedSession.Playback.Action(category, moddedSession._profile);
					moddedSession.Visual?.RebindAnchors();
				}
			}
		}

		private ModdedSession(NCreature actor, NCombatRoom room, CombatState combat)
		{
