			_room = room;
			_combat = combat;
			_body = actor.Body;
			_tree = ((Node)room).GetTree();
			_profile = ModdedAssets.Get().Profiles.Single((ModdedAssets.Profile p) => p.Hash == SpineGuard.Get(_body, CoolheadedAssets.Get()).Profile.Hash);
			((Node)actor).TreeExiting += Dispose;
			((Node)room).TreeExiting += Dispose;
