				if (!CoolheadedSession.Allowed || !AnimationSettings.Current.Enabled || !AnimationSettings.Current.ModdedEnabled || !CombatManager.Instance.IsInProgress || CombatManager.Instance.IsEnding || !_actor.Entity.IsAlive || _actor.IsPlayingDeathAnimation || _actor.Entity.CombatState != _combat)
				{
