	internal interface IMulticastEffect : IDisposable
	{
		MulticastCall Call { get; }

		bool Advance(double delta);
	}
	internal sealed class MulticastSession : IDisposable
	{
		private static readonly Dictionary<NCreature, MulticastSession> Sessions = new Dictionary<NCreature, MulticastSession>(ReferenceEqualityComparer.Instance);

		private readonly NCreature _actor;

		internal readonly NCombatRoom Room;

		private readonly object _combat;

		private readonly SceneTree _tree;

		internal readonly List<IMulticastEffect> Effects = new List<IMulticastEffect>();

		private bool _disposed;

		internal static int ActiveCount => Sessions.Count;

		internal static bool Allowed(bool quad)
		{
			if (MulticastContext.Supported && CoolheadedSession.Allowed && AnimationSettings.Current.Enabled && (quad ? AnimationSettings.Current.QuadcastEnabled : AnimationSettings.Current.DualcastEnabled) && CombatManager.Instance.IsInProgress)
			{
				return !CombatManager.Instance.IsEnding;
			}
			return false;
		}

		private MulticastSession(NCreature actor, NCombatRoom room)
		{
			_actor = actor;
			Room = room;
			_combat = actor.Entity.CombatState;
			_tree = ((Node)room).GetTree();
			((Node)actor).TreeExiting += Dispose;
			((Node)room).TreeExiting += Dispose;
			_tree.ProcessFrame += Frame;
		}

		internal static MulticastSession? For(MulticastInvocation invoke)
		{
			if (invoke.call.Live && invoke.Source != null)
			{
				NCombatRoom instance = NCombatRoom.Instance;
				if (instance != null)
				{
					NCreature creatureNode = invoke.call.card.Owner.Creature.GetCreatureNode();
					if (creatureNode != null && creatureNode.Entity.CombatState is CombatState && creatureNode.Entity.IsAlive)
					{
						if (!Sessions.TryGetValue(creatureNode, out MulticastSession value))
						{
							value = new MulticastSession(creatureNode, instance);
							Sessions.Add(creatureNode, value);
						}
						return value;
					}
				}
			}
			return null;
		}

		internal static void Emit(MulticastInvocation invoke)
		{
			MulticastSession multicastSession = For(invoke);
			if (multicastSession == null)
			{
				return;
			}
			OrbModel orb = invoke.orb;
			if (!(orb is FrostOrb))
			{
				if (!(orb is GlassOrb))
				{
					if (orb is PlasmaOrb)
					{
						multicastSession.Effects.Add(new MulticastPlasma(invoke, multicastSession.Room));
					}
					return;
				}
				MulticastGlass multicastGlass = multicastSession.Effects.OfType<MulticastGlass>().FirstOrDefault((MulticastGlass e) => e.Call == invoke.call && e.Orb == invoke.orb);
				if (multicastGlass == null)
				{
					multicastSession.Effects.Add(new MulticastGlass(invoke));
				}
				else
				{
					multicastGlass.Pulse();
				}
				multicastSession.Effects.Add(MulticastParticles.Glass(invoke, multicastSession.Room));
			}
			else
			{
				multicastSession.Effects.Add(new MulticastFrost(invoke, multicastSession._actor));
				MulticastOrbShatter multicastOrbShatter = multicastSession.Effects.OfType<MulticastOrbShatter>().FirstOrDefault((MulticastOrbShatter e) => e.Orb == invoke.orb);
				if (multicastOrbShatter == null)
				{
					multicastSession.Effects.Add(new MulticastOrbShatter(invoke));
				}
				else
				{
					multicastOrbShatter.Pulse();
				}
			}
		}

		internal static void Projectile(MulticastInvocation invoke, Node2D node)
		{
			MulticastSession multicastSession = For(invoke);
			multicastSession?.Effects.Add(new MulticastDark(invoke, node, multicastSession.Room));
		}

		internal static void NativeEffect(MulticastInvocation invoke, Node2D node, string path)
		{
			MulticastSession multicastSession = For(invoke);
			if (multicastSession != null)
			{
				if (invoke.orb is LightningOrb && path == "vfx/vfx_attack_lightning")
				{
					multicastSession.Effects.Add(new MulticastLightning(invoke, node));
				}
				else if (invoke.orb is DarkOrb && path.Contains("vfx_dark_orb"))
				{
					multicastSession.Effects.Add(new MulticastDarkTint(invoke, node));
				}
			}
		}

		private void Frame()
		{
			if (_disposed)
			{
				return;
			}
			try
			{
				if (!CoolheadedSession.Allowed || CombatManager.Instance.IsEnding || !_actor.Entity.IsAlive || _actor.IsPlayingDeathAnimation || _combat != _actor.Entity.CombatState)
				{
					Dispose();
				}
				else
				{
					if (_tree.Paused || !((Node)_actor).CanProcess())
					{
						return;
					}
					for (int num = Effects.Count - 1; num >= 0; num--)
					{
						if (!Allowed(Effects[num].Call.Quad) || !Effects[num].Advance(((Node)_actor).GetProcessDeltaTime()))
						{
							Effects[num].Dispose();
							Effects.RemoveAt(num);
						}
					}
					if (Effects.Count == 0)
					{
						Dispose();
					}
				}
			}
			catch (Exception error)
			{
				ModEntry.Log(error);
				Dispose();
			}
		}

		internal static void Cancel(MulticastCall call)
		{
			MulticastSession[] array = Sessions.Values.ToArray();
			foreach (MulticastSession multicastSession in array)
			{
				for (int num = multicastSession.Effects.Count - 1; num >= 0; num--)
				{
					if (multicastSession.Effects[num].Call == call)
					{
						multicastSession.Effects[num].Dispose();
						multicastSession.Effects.RemoveAt(num);
					}
				}
			}
		}

		internal static void Reset()
		{
			MulticastSession[] array = Sessions.Values.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Dispose();
			}
		}

		public void Dispose()
		{
			if (_disposed)
			{
				return;
			}
			_disposed = true;
			foreach (IMulticastEffect effect in Effects)
			{
				effect.Dispose();
			}
			Effects.Clear();
			if (GodotObject.IsInstanceValid((GodotObject)(object)_tree))
			{
				_tree.ProcessFrame -= Frame;
			}
			if (GodotObject.IsInstanceValid((GodotObject)(object)_actor))
			{
				((Node)_actor).TreeExiting -= Dispose;
			}
			if (GodotObject.IsInstanceValid((GodotObject)(object)Room))
			{
				((Node)Room).TreeExiting -= Dispose;
			}
			Sessions.Remove(_actor);
		}
	}
