	internal sealed class SupercriticalPlayback
	{
		internal sealed class Cast(int id)
		{
			internal readonly int Id = id;

			internal double Age;

			internal float Energy => SupercriticalAssets.Smooth(0.0, 0.28, Age) * (1f - SupercriticalAssets.Smooth(0.74, 1.56, Age));
		}

		internal readonly List<Cast> Casts = new List<Cast>();

		internal int Created;

		internal int Completed;

		internal float Energy
		{
			get
			{
				if (Casts.Count != 0)
				{
					return Casts.Max((Cast c) => c.Energy);
				}
				return 0f;
			}
		}

		internal float EnergySum => Casts.Sum((Cast c) => c.Energy);

		internal void Trigger()
		{
			Casts.Add(new Cast(++Created));
		}

		internal void Advance(double dt)
		{
			if (dt <= 0.0)
			{
				return;
			}
			for (int num = Casts.Count - 1; num >= 0; num--)
			{
				Cast cast = Casts[num];
				cast.Age += dt;
				if (cast.Age >= 1.559999999)
				{
					Casts.RemoveAt(num);
					Completed++;
				}
			}
		}

		internal void Cancel()
		{
			Casts.Clear();
		}
	}
