	internal sealed class TurboPlayback
	{
		internal const double Duration = 1.5666666666666667;

		internal double Age { get; private set; } = 1.5666666666666667;

		internal int Generation { get; private set; }

		internal bool CoreActive { get; private set; }

		internal bool Active => Age < 1.5666666666666667;

		internal void Start()
		{
			Age = 0.0;
			Generation++;
			CoreActive = true;
		}

		internal void InterruptCore()
		{
			CoreActive = false;
		}

		internal void Advance(double dt)
		{
			Age = Math.Min(1.5666666666666667, Age + Math.Max(0.0, dt));
		}

		internal void Cancel()
		{
			Age = 1.5666666666666667;
		}
	}
	internal sealed class TurboSession : IDisposable
	{
		private static readonly Dictionary<NCreature, TurboSession> Sessions = new Dictionary<NCreature, TurboSession>(ReferenceEqualityComparer.Instance);

		private static readonly ConditionalWeakTable<object, object> Plays = new ConditionalWeakTable<object, object>();

		internal readonly TurboPlayback Playback = new TurboPlayback();

		private readonly NCreature _actor;

		private readonly NCombatRoom _room;

		private readonly CombatState _combat;

		private readonly SceneTree _tree;

		private Node2D _body;

		private ulong _lastFrame;

		private bool _disposed;

		internal static int ActiveCount => Sessions.Count;

		internal NativeTurbo? Visual { get; private set; }

		internal static double LastStartCpuMilliseconds { get; private set; }

		internal static TurboSession? For(NCreature actor)
		{
			return Sessions.GetValueOrDefault(actor);
		}

		internal static void Start(Turbo card, object? play = null)
		{
			if (!CoolheadedSession.Allowed || !AnimationSettings.Current.Enabled || !AnimationSettings.Current.TurboEnabled || !CombatManager.Instance.IsInProgress || CombatManager.Instance.IsEnding)
			{
				return;
			}
			Creature creature = ((CardModel)card).Owner.Creature;
			if (((object)((CardModel)card).Owner.Character).GetType().Name != "Defect" || !creature.IsAlive)
			{
				return;
			}
			ICombatState combatState = creature.CombatState;
			CombatState val = (CombatState)(object)((combatState is CombatState) ? combatState : null);
			if (val == null || CombatManager.Instance.DebugOnlyGetState() != val)
			{
				return;
			}
			NCreature creatureNode = creature.GetCreatureNode();
			NCombatRoom instance = NCombatRoom.Instance;
			if (creatureNode == null || instance == null || !GodotObject.IsInstanceValid((GodotObject)(object)creatureNode) || !((Node)creatureNode).IsInsideTree() || creatureNode.IsPlayingDeathAnimation || !creatureNode.HasSpineAnimation || SpineGuard.Get(creatureNode.Body, CoolheadedAssets.Get()) == null)
			{
				return;
			}
			if (play != null)
			{
				if (Plays.TryGetValue(play, out object _))
				{
					return;
				}
				Plays.Add(play, new object());
			}
			long timestamp = Stopwatch.GetTimestamp();
			TurboSession turboSession = For(creatureNode);
			if (turboSession == null)
			{
				turboSession = new TurboSession(creatureNode, instance, val);
				Sessions.Add(creatureNode, turboSession);
			}
			else
			{
				turboSession.Synchronize();
			}
			turboSession.Playback.Start();
			turboSession.RefreshBinding();
			turboSession.Visual?.Restart();
			LastStartCpuMilliseconds = Stopwatch.GetElapsedTime(timestamp).TotalMilliseconds;
		}

		private TurboSession(NCreature actor, NCombatRoom room, CombatState combat)
		{
			_actor = actor;
			_room = room;
			_combat = combat;
			_body = actor.Body;
			_tree = ((Node)room).GetTree();
			_lastFrame = Engine.GetProcessFrames();
			((Node)actor).TreeExiting += Dispose;
			((Node)room).TreeExiting += Dispose;
			actor.Entity.Died += Died;
			_tree.ProcessFrame += Frame;
		}

		private void DropVisual()
		{
			NativeTurbo? visual = Visual;
			Visual = null;
			visual?.Dispose();
		}

		private void RefreshBinding()
		{
			Node2D body = _actor.Body;
			if (Visual != null && (body != _body || !Visual.Current))
			{
				DropVisual();
			}
			_body = body;
			if (Visual == null && GodotObject.IsInstanceValid((GodotObject)(object)body) && ((Node)body).IsInsideTree() && ((GodotObject)body).HasMethod(StringName.op_Implicit("get_skeleton_data_res")) && SpineGuard.Get(body, CoolheadedAssets.Get()) != null)
			{
				Visual = new NativeTurbo(body, Playback);
			}
		}

		private void Synchronize()
		{
			if (!_disposed && !_tree.Paused && ((Node)_actor).CanProcess())
			{
				ulong processFrames = Engine.GetProcessFrames();
				if (processFrames != _lastFrame)
				{
					_lastFrame = processFrames;
					double processDeltaTime = ((Node)_actor).GetProcessDeltaTime();
					Playback.Advance(processDeltaTime);
				}
			}
		}

		private void Died(Creature creature)
		{
			Dispose();
		}

		private void Frame()
		{
			if (_disposed)
			{
				return;
			}
			try
			{
				if (!CoolheadedSession.Allowed || !AnimationSettings.Current.Enabled || !AnimationSettings.Current.TurboEnabled || !CombatManager.Instance.IsInProgress || CombatManager.Instance.IsEnding || !_actor.Entity.IsAlive || _actor.IsPlayingDeathAnimation || _actor.Entity.CombatState != _combat)
				{
					Dispose();
				}
				else if (!_tree.Paused && ((Node)_actor).CanProcess())
				{
					Synchronize();
					if (!Playback.Active)
					{
						Dispose();
					}
					else
					{
						RefreshBinding();
					}
				}
			}
			catch (Exception error)
			{
				ModEntry.Log(error);
				Dispose();
			}
		}

		internal static void Reset()
		{
			TurboSession[] array = Sessions.Values.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Dispose();
			}
		}

		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				Playback.Cancel();
				DropVisual();
				if (GodotObject.IsInstanceValid((GodotObject)(object)_tree))
				{
					_tree.ProcessFrame -= Frame;
				}
				if (GodotObject.IsInstanceValid((GodotObject)(object)_actor))
				{
					((Node)_actor).TreeExiting -= Dispose;
				}
				if (GodotObject.IsInstanceValid((GodotObject)(object)_room))
				{
					((Node)_room).TreeExiting -= Dispose;
				}
				_actor.Entity.Died -= Died;
				if (For(_actor) == this)
				{
					Sessions.Remove(_actor);
				}
			}
		}
	}
	[HarmonyPatch(typeof(Turbo), "OnPlay")]
	internal static class TurboPlayedPatch
	{
		[HarmonyPrefix]
		private static void Prefix(Turbo __instance, object? cardPlay)
		{
			try
			{
				TurboSession.Start(__instance, cardPlay);
			}
			catch (Exception error)
			{
				ModEntry.Log(error);
			}
		}
	}
	[HarmonyPatch(typeof(BulkUp), "OnPlay")]
